use crate::aap::caps::http_client;
use crate::wasi::clocks::wall_clock;

struct Node;

/// 9999-12-31T23:59:59Z: the last instant whose date has a four-digit year.
const MAX_DATE_SECONDS: u64 = 253_402_300_799;

const ENRICH_BASE: &str = "https://metadata.internal.example/enrich?q=";

fn percent_encode(input: &str) -> String {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut out = String::with_capacity(input.len());
    for &b in input.as_bytes() {
        let unreserved = b.is_ascii_alphanumeric() || matches!(b, b'-' | b'_' | b'.' | b'~');
        if unreserved {
            out.push(b as char);
        } else {
            out.push('%');
            out.push(HEX[(b >> 4) as usize] as char);
            out.push(HEX[(b & 0x0F) as usize] as char);
        }
    }
    out
}

/// Days since 1970-01-01 to (year, month, day), proleptic Gregorian.
fn civil_from_days(z: i64) -> (i64, u32, u32) {
    let z = z + 719_468;
    let era = if z >= 0 { z } else { z - 146_096 } / 146_097;
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
    let y = if m <= 2 { y + 1 } else { y };
    (y, m, d)
}

fn format_date(seconds: u64) -> String {
    let clamped = seconds.min(MAX_DATE_SECONDS);
    let days = (clamped / 86_400) as i64;
    let (y, m, d) = civil_from_days(days);
    let y = y.clamp(0, 9999);
    format!("{:04}-{:02}-{:02}", y, m, d)
}

impl Guest for Node {
    fn run(tick: Tick) -> RunInfo {
        // Enrichment fetch (approved grant extension). Its result does not
        // affect the output; a transport failure is tolerated as a value.
        let url = format!("{}{}", ENRICH_BASE, percent_encode(&tick.reason));
        let _enrichment = http_client::fetch(&url);

        let now = wall_clock::now();
        let date = format_date(now.seconds);
        RunInfo {
            date,
            started: now.seconds,
        }
    }
}

export!(Node);
```

